"""Signal model for trading signals generated by strategies."""

from datetime import datetime

from sqlalchemy import JSON, Boolean, Column, DateTime, ForeignKey, Index, Integer, Numeric, String
from sqlalchemy.orm import relationship

from src.infrastructure.base_model import BaseModel


class Signal(BaseModel):
    """Signal model for tracking trading signals generated by strategies."""

    __tablename__ = "signals"
    __table_args__ = (
        Index("idx_strategy_symbol", "strategy_id", "symbol"),
        Index("idx_generated_at", "generated_at"),
    )

    strategy_id = Column(
        Integer, ForeignKey("strategies.id", ondelete="CASCADE"), nullable=False, index=True
    )
    symbol = Column(String(10), nullable=False)
    signal_type = Column(String(10), nullable=False)  # 'buy', 'sell', 'hold'
    strength = Column(Numeric(5, 2), nullable=True)  # Signal confidence 0-100
    price = Column(Numeric(15, 4), nullable=False)
    indicators = Column(JSON, nullable=True)  # Technical indicator values at signal time
    generated_at = Column(DateTime, nullable=False, default=datetime.utcnow, index=True)
    executed = Column(Boolean, default=False, nullable=False)

    # Relationship
    strategy = relationship("Strategy", back_populates="signals")

    def to_dict(self) -> dict:
        """Convert signal to dictionary.

        Returns:
            Dictionary representation of signal
        """
        return {
            "id": self.id,
            "strategy_id": self.strategy_id,
            "symbol": self.symbol,
            "signal_type": self.signal_type,
            "strength": float(self.strength) if self.strength else None,
            "price": float(self.price) if self.price else None,
            "indicators": self.indicators,
            "generated_at": self.generated_at.isoformat() if self.generated_at else None,
            "executed": self.executed,
            "created_at": self.created_at.isoformat() if self.created_at else None,
        }

    def __repr__(self) -> str:
        """String representation of signal."""
        return f"<Signal(id={self.id}, symbol={self.symbol}, type={self.signal_type})>"
